 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == dx == 0:
                            continue
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                                (yy, xx) not in seen and grid[yy][xx] == color):
                            seen.add((yy, xx))
                            q.append((yy, xx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            area = (y1 - y0 + 1) * (x1 - x0 + 1)
            # True objects are noisy filled rectangles; isolated speckles are discarded.
            if y1 > y0 and x1 > x0 and len(cells) / area >= 0.55:
                for yy in range(y0, y1 + 1):
                    for xx in range(x0, x1 + 1):
                        out[yy][xx] = color
    return out


